  'YII=';

function sha256(buf) {
  return crypto.createHash('sha256').update(buf).digest('hex');
}

const bytes = Buffer.from(BASE64, 'base64');

if (bytes.length !== EXPECTED_SIZE) {
  throw new Error(`Decoded size mismatch: ${bytes.length} != ${EXPECTED_SIZE}`);
}

if (!bytes.subarray(0, 8).equals(Buffer.from([0x89,0x50,0x4e,0x47,0x0d,0x0a,0x1a,0x0a]))) {
  throw new Error('PNG signature invalid before write');
}

const decodedHash = sha256(bytes);
if (decodedHash !== EXPECTED_SHA256) {
  throw new Error(`Decoded SHA256 mismatch: ${decodedHash}`);
}

// PNG IHDR width/height are big-endian at bytes 16..23.
const width = bytes.readUInt32BE(16);
const height = bytes.readUInt32BE(20);
if (width !== 1184 || height !== 159) {
  throw new Error(`PNG dimensions mismatch: ${width}x${height}`);
}

fs.mkdirSync(path.dirname(TARGET), { recursive: true });
fs.writeFileSync(TARGET, bytes);

const written = fs.readFileSync(TARGET);
const writtenHash = sha256(written);

if (written.length !== EXPECTED_SIZE || writtenHash !== EXPECTED_SHA256) {
  throw new Error(
    `Post-write verification failed: size=${written.length}, sha256=${writtenHash}`
  );
}

console.log('OFFICIAL_LOGO_RESTORE_OK');
console.log(`TARGET=${TARGET}`);
console.log(`SIZE=${written.length}`);
console.log(`SHA256=${writtenHash}`);
console.log(`DIMENSIONS=${width}x${height}`);
